const $=s=>document.querySelector(s);
const bots=[{id:'octacon',name:'Octacon',role:'Implementation',scope:'Contributor',responsibility:'Owns checkout fixes and implementation reviews.',tasks:[{id:'DEMO-12',title:'Fix double-charge on retry',status:'In progress',note:'Implementation under review.',detail:'Reproduce retry behaviour and ensure the same payment cannot be charged twice.'},{id:'DEMO-13',title:'Add payment idempotency keys',status:'Blocked',note:'Waiting for the API contract.',detail:'Blocked by agreement on the idempotency-key format. Human input is needed before implementation continues.'},{id:'DEMO-16',title:'Review checkout logging',status:'Queued',note:'Not started.',detail:'Check that failures can be traced without logging payment details.'}]},{id:'quan',name:'Quan',role:'Testing & review',scope:'Reviewer',responsibility:'Checks payment behaviour and verifies fixes before release.',tasks:[{id:'DEMO-14',title:'Load-test the checkout flow',status:'In progress',note:'Test setup in progress.',detail:'Exercise repeated requests and compare outcomes against the agreed acceptance criteria.'},{id:'DEMO-17',title:'Verify the retry fix',status:'Queued',note:'Starts after the fix is ready.',detail:'Run the reproduction and regression cases against the implementation.'}]},{id:'remii',name:'Remii',role:'Research',scope:'Contributor',responsibility:'Provides evidence and technical comparisons when needed.',tasks:[]}];
let expanded=new Set(['octacon']);let openStatus={};
const statusClass=s=>s==='Blocked'?'blocked':s==='In progress'?'inprogress':'';
function render(){const q=$('#search').value.toLowerCase(),f=$('#filter').value;const visible=bots.filter(b=>(b.name+' '+b.role).toLowerCase().includes(q)&&(f==='all'||(f==='blocked'?b.tasks.some(t=>t.status==='Blocked'):b.tasks.length===0)));$('#members').innerHTML=visible.map(b=>{const blocked=b.tasks.filter(t=>t.status==='Blocked').length;const bar=['In progress','Blocked','Queued'].map(s=>{const count=b.tasks.filter(t=>t.status===s).length;return count?`<span class="${s==='In progress'?'working':s==='Blocked'?'blocked-fill':'queued'}" style="width:${count/b.tasks.length*100}%"></span>`:''}).join('');return `<details class="member" data-bot="${b.id}" ${expanded.has(b.id)?'open':''}><summary aria-controls="body-${b.id}"><span class="avatar" aria-hidden="true">${b.name[0]}</span><span class="identity"><strong>${b.name}</strong><small>${b.role}</small></span><span class="workload"><span class="counts"><span>${b.tasks.length} open</span>${blocked?`<span class="blocked">incl. ${blocked} blocked</span>`:b.tasks.length?'':'<span>Unassigned</span>'}</span><span class="workbar" role="img" aria-label="${['In progress','Blocked','Queued'].map(s=>`${b.tasks.filter(t=>t.status===s).length} ${s.toLowerCase()}`).join(', ')}. Work mix, not capacity.">${bar}</span></span><span class="chevron" aria-hidden="true">›</span></summary><div class="expanded" id="body-${b.id}"><div class="expanded-top"><p>${b.responsibility}</p><span class="role-label">${b.scope}</span></div>${(()=>{if(!b.tasks.length)return '<p class="no-work">No work assigned in this project. This does not indicate runtime availability.</p>';const order=['Blocked','In progress','Queued'];const active=openStatus[b.id]!==undefined?openStatus[b.id]:order.find(x=>b.tasks.some(t=>t.status===x));const cards=order.map(st=>{const n=b.tasks.filter(t=>t.status===st).length;const cls=st==='Blocked'?'blocked':st==='In progress'?'inprogress':'queued';return `<button class="status-card ${cls}" data-drill="${b.id}|${st}" ${n?'':'disabled'} aria-pressed="${active===st}"><span class="sc-count">${n}</span><span class="sc-label">${st}</span></button>`}).join('');const list=active?b.tasks.filter(t=>t.status===active).map(t=>`<button class="task" data-task="${t.id}"><span><strong>${t.title}</strong><small>${t.id} · ${t.note}</small></span><span class="tag ${statusClass(active)}">${active}</span><span aria-hidden="true">›</span></button>`).join(''):'';return `<div class="status-cards">${cards}</div>${active?`<div class="drill"><h3 class="assignment-label">${active} · ${b.tasks.filter(t=>t.status===active).length}</h3>${list}</div>`:'<p class="drill-hint">Select a status to see its work.</p>'}`})()}<div class="member-actions"><div><button class="link" data-profile="${b.id}">View profile</button><button class="link" data-assign="${b.id}">Manage assignments</button></div><small>Runtime status not connected</small></div></div></details>`}).join('');$('#empty').hidden=visible.length!==0;$('#announce').textContent=`${visible.length} members shown`;document.querySelectorAll('.member').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)expanded.add(d.dataset.bot);else expanded.delete(d.dataset.bot)}))}
function panel(kind,title,body){$('#panel-kind').textContent=kind;$('#panel-title').textContent=title;$('#panel-content').innerHTML=body;$('#inspector').showModal()}
$('#close').onclick=()=>$('#inspector').close();
$('#search').oninput=render;$('#filter').onchange=render;$('#reset').onclick=()=>{$('#search').value='';$('#filter').value='all';render();$('#search').focus()};
$('#theme').onchange=e=>{$('.dockyard-root').dataset.theme=e.target.value};
$('#explain').onclick=()=>panel('Workload','Work mix, not utilisation',`<p>The bar divides this member’s open items into in progress, blocked and queued work. Each item has equal weight.</p><ul><li>Blue: in progress.</li><li>Red: blocked.</li><li>Grey: queued.</li></ul><p>Counts are also available as text. Three tasks do not necessarily mean more effort than one task. No capacity percentage or online status is inferred.</p><p class="panel-note">A future capacity view needs actual concurrency limits, execution data or reliable effort estimates. Those are not part of this card study.</p>`);
$('#review-notes').onclick=()=>panel('Design review','One component for sign-off',`<p>This is a focused expandable member card, not a replacement Team screen.</p><ul><li>Collapsed: identity, role and current project work mix.</li><li>Expanded: responsibility and tasks, with blocked work first.</li><li>Side panel: task context and profile details.</li><li>Multiple members can stay expanded for comparison.</li></ul><p>Adapted from your resource-card reference. Deliberately omitted utilisation percentages, hour allocations, skill-tag walls and repeated KPI cards.</p><p>All tasks, responsibilities and role assignments here are fictional examples. Manage assignments previews an entry point; it does not implement or replace the existing transfer workflow.</p><p class="panel-note">Sign-off applies to this component’s design only. No application changes or next-screen work starts from this preview.</p>`);
document.addEventListener('click',e=>{const dr=e.target.closest('[data-drill]');if(dr&&!dr.disabled){const i=dr.dataset.drill.indexOf('|');const bot=dr.dataset.drill.slice(0,i),st=dr.dataset.drill.slice(i+1);openStatus[bot]=openStatus[bot]===st?null:st;render();return}const t=e.target.closest('[data-task]'),p=e.target.closest('[data-profile]'),a=e.target.closest('[data-assign]');if(t){const b=bots.find(b=>b.tasks.some(x=>x.id===t.dataset.task));const item=b.tasks.find(x=>x.id===t.dataset.task);panel('Task · '+item.id,item.title,`<span class="tag ${statusClass(item.status)}">${item.status}</span><p>${item.detail}</p><dl><dt>Owner</dt><dd>${b.name}</dd><dt>Project</dt><dd>Checkout reliability rebuild</dd><dt>Next step</dt><dd>${item.note}</dd></dl><p class="panel-note">Sample task. In the application, “Open full details” would open the existing task screen. That route is not connected in this component study.</p>`)}else if(p){const b=bots.find(x=>x.id===p.dataset.profile);panel('Bot profile',b.name,`<p>${b.responsibility}</p><dl><dt>Specialism</dt><dd>${b.role}</dd><dt>Project role</dt><dd>${b.scope}</dd><dt>Assigned here</dt><dd>${b.tasks.length} open work items</dd><dt>Runtime</dt><dd>Not connected — membership is not proof of availability.</dd></dl><p class="panel-note">Capabilities, permissions and cross-project assignments belong in the full existing profile, not repeated on every card.</p>`)}else if(a){const b=bots.find(x=>x.id===a.dataset.assign);panel('Management entry point',b.name+' · assignments',`<p>This action should open the existing assignment or handover flow with ${b.name} and this project already selected.</p><p>That flow must retain its current permission checks, affected-work review and interrupted-transfer recovery.</p><p class="panel-note">Navigation preview only. No task is reassigned, no member is removed and no simplified transfer workflow is substituted here.</p>`)}});
render();
